#include <iostream>
#include <string>

int main() {
    std::string line;
    std::getline(std::cin, line);
    int count = 0;
    int start = 0;
    int end = 0;
    int length = line.length();

    while (start < length) {
        while (end < length && line[end] == line[start]) {
            end++;
        }
        if ((end - start) % 2 == 0) {
            count++;
        }
        start = end;
    }
    std::cout << count << std::endl;
    return 0;
}
